import type { ForecastScenario, ScenarioPoint } from '../lib/types'
import { NATIONAL_PRICE } from '../data/prices'
import { LAST_MEASURED_QUARTER, addQuarters } from '../lib/quarters'
import { pctChange, std } from '../lib/stats'
import { VALUATION } from './valuation'

/**
 * Forecast engine (full derivation in docs/FORECAST_METHODOLOGY.md §5).
 *
 * NOT a price extrapolation. Quarterly growth is generated by a documented
 * factor model:
 *
 *   g(t) = w_m·momentum(t) + w_f·fundamental(t) + w_v·valuationPull(t)
 *
 *   momentum(t)      – observed recent growth, decaying with half-life 3 q
 *                      (markets are persistent but momentum fades)
 *   fundamental(t)   – scenario-dependent structural growth from: expected wage
 *                      growth, mortgage-rate path, supply gap, migration/demography,
 *                      construction costs, policy stance (per-scenario table below)
 *   valuationPull(t) – mean-reversion: −λ · composite misvaluation, distributed
 *                      over 12 quarters (overvalued markets grow below fundamentals)
 *
 * Confidence intervals: σ of historical 4-quarter changes (≈ observed forecast
 * error of a naive model) scaled by √horizon and a scenario uncertainty factor.
 * Scenario probabilities are analyst priors (documented) — not model outputs.
 */

export interface ScenarioAssumption {
  id: 'optimistic' | 'base' | 'pessimistic'
  label: string
  probability: number
  /** structural quarterly growth from fundamentals, % q/q at horizon start */
  fundamentalQ: number
  /** how fast fundamentals converge to long-run trend (0.8 %/q ≈ 3.2 % p.a. nominal, pod rastom miezd) */
  fundamentalDecay: number
  /** valuation mean-reversion intensity per quarter (share of gap closed) */
  reversion: number
  /** how much of the observed market momentum survives the scenario's shock */
  momentumFactor: number
  uncertainty: number
  assumptions: string[]
}

