export const FORECAST_HORIZON_Q = 20 // 5 years

export function buildForecasts(): ForecastScenario[] {
  const v = NATIONAL_PRICE.values
  const last = v[v.length - 1]!
  const yoyHist = pctChange(v, 4).filter((x): x is number => x != null)
  const sigmaYoY = std(yoyHist) // ≈ historical dispersion of 4Q changes, pp

  // starting momentum: mean of last 2 quarterly growth rates
  const qoq = pctChange(v, 1)
  const m0 = ((qoq[qoq.length - 1] ?? 0) + (qoq[qoq.length - 2] ?? 0)) / 2

  const W_MOMENTUM = 0.45
  const W_FUND = 0.4
  const W_VAL = 0.15
  const MOMENTUM_DECAY = 0.7943 // half-life 3 quarters

  return SCENARIOS.map((sc) => {
    const points: ScenarioPoint[] = []
    let price = last
    let momentum = m0 * sc.momentumFactor
    let fundamental = sc.fundamentalQ
    let valuationGap = VALUATION.composite // % overvaluation, decays as prices adjust

    for (let h = 1; h <= FORECAST_HORIZON_Q; h++) {
      momentum *= MOMENTUM_DECAY
      fundamental = 0.8 + (fundamental - 0.8) * sc.fundamentalDecay
      // valuation drag: reversion×10 ≈ share of the misvaluation gap (in %) converted
      // to a q/q growth penalty; base scenario ≈ −0.2 pp/q at a +13 % gap
      const pull = -sc.reversion * 10 * valuationGap
      const g = W_MOMENTUM * momentum + W_FUND * fundamental + W_VAL * pull // % q/q
      price = price * (1 + g / 100)
      valuationGap = valuationGap * (1 - sc.reversion * 4) + (g - 1.2) * 0.15 // gap grows if growth ≫ income trend

      const sigmaH = sigmaYoY * Math.sqrt(h / 4) * sc.uncertainty * 0.55
      points.push({
        quarter: addQuarters(LAST_MEASURED_QUARTER, h),
        value: Math.round(price),
        lo: Math.round(price * (1 - (sigmaH * 1.28) / 100)), // ~80 % interval
        hi: Math.round(price * (1 + (sigmaH * 1.28) / 100)),
      })
    }

    return {
      id: sc.id,
      label: sc.label,
      probability: sc.probability,
      assumptions: sc.assumptions,
      points,
    }
  })
}

export const FORECASTS = buildForecasts()

export function horizonSummary(): {
  horizon: string
  quarters: number
  scenarios: { id: string; label: string; price: number; pct: number; lo: number; hi: number }[]
}[] {
  const last = NATIONAL_PRICE.values[NATIONAL_PRICE.values.length - 1]!
  return [
    { horizon: '12 mesiacov', quarters: 4 },
    { horizon: '3 roky', quarters: 12 },
    { horizon: '5 rokov', quarters: 20 },
  ].map(({ horizon, quarters }) => ({
    horizon,
    quarters,
    scenarios: FORECASTS.map((f) => {
      const p = f.points[quarters - 1]
      return {
        id: f.id,
        label: f.label,
        price: p.value,
        pct: ((p.value - last) / last) * 100,
        lo: p.lo,
        hi: p.hi,
      }
    }),
  }))
}

export const HORIZONS = horizonSummary()
